<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
type Row=Record<string,any>
const props=defineProps<{host:Row,api:(path:string,method?:string,body?:any)=>Promise<any>}>()
const emit=defineEmits<{close:[]}>()
const engine=ref('sing-box'),version=ref(''),release=ref<Row|null>(null),kernels=ref<Row[]>([]),operations=ref<Row[]>([]),busy=ref(false),error=ref(''),notice=ref('')
const current=computed(()=>kernels.value.find(k=>k.engine===engine.value)),active=computed(()=>operations.value.some(o=>['queued','downloading','validating'].includes(o.state)))
let timer:ReturnType<typeof setTimeout>|undefined,alive=true
function schedule(){clearTimeout(timer);if(active.value&&alive)timer=setTimeout(()=>{if(document.visibilityState==='visible')void load().catch(e=>{error.value=String(e);schedule()});else schedule()},8000)}
async function load(){const [k,o]=await Promise.all([props.api('hosts/'+props.host.id+'/kernels'),props.api('hosts/'+props.host.id+'/engine-updates')]);if(!alive)return;kernels.value=k;operations.value=o;schedule()}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
function latest(){void run(async()=>{release.value=await props.api('engine-releases?engine='+engine.value+'&version=latest');version.value=release.value!.version})}
function install(latest=false){void run(async()=>{const result=await props.api('hosts/'+props.host.id+'/engine-updates','POST',{engine:engine.value,version:latest?'latest':version.value.trim()});notice.value='已排队 '+engine.value+' '+result.version+'，等待 Agent 校验与切换';await load()})}
const states:Record<string,string>={queued:'等待 Agent',downloading:'下载并核对官方摘要',validating:'检查现有配置并切换',succeeded:'已切换',failed:'失败，保留或回退原版本'}
onMounted(()=>void run(load));onUnmounted(()=>{alive=false;clearTimeout(timer)})
</script>
<template><div class="modal-backdrop"><section class="modal engine-manager" role="dialog" aria-modal="true" aria-label="官方内核版本"><div class="modal-heading"><div><h2>{{host.name}} · 内核版本</h2><p class="muted">官方发行文件 · SHA-256 校验 · 版本切换与失败回退</p></div><button class="secondary" @click="emit('close')">关闭</button></div><div class="form-content"><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><div class="fields"><label>内核<select v-model="engine" @change="release=null;version=''"><option value="sing-box">sing-box 官方版</option><option value="xray">Xray-core 官方版</option></select></label><div><span class="muted">当前 Agent 回报</span><p>{{current?.version??'尚未回报'}} <small>{{current?.ready?'可用':'待检查'}}</small></p></div><label>指定版本<input v-model="version" aria-label="指定内核版本" placeholder="例如 1.14.4 / v26.10.21"></label><div class="row-actions"><button class="secondary" :disabled="busy" @click="latest">查询最新稳定版</button><button class="primary" :disabled="busy||active" @click="install(true)">更新至最新稳定版</button><button class="secondary" :disabled="busy||active||!version.trim()" @click="install()">安装 / 切换指定版本</button></div></div><p v-if="release" class="notice">官方最新：{{release.version}} · {{release.published_at?new Date(release.published_at).toLocaleString():''}}</p><p class="form-note">需要 Agent 0.17 或更新版本。下载期间现有内核继续运行；候选版本通过现有配置检查后，短暂重启该内核的全部入站。旧版本保留用于回退。降级也必须通过检查。仅支持官方发行文件，不接收自定义下载地址或 shell 命令。</p><div class="section-heading"><h3>更新记录</h3><button class="text-button" :disabled="busy" @click="run(load)">刷新状态</button></div><div class="engine-history"><article v-for="o in operations" :key="o.id"><div><strong>{{o.engine}} {{o.version}}</strong><small>{{states[o.state]??o.state}} · {{new Date(o.updated_at).toLocaleString()}}</small><p v-if="o.error" class="error">{{o.error}}</p></div><button class="text-button" @click="engine=o.engine;version=o.version">选择此版本</button></article><p v-if="!operations.length" class="muted">尚无更新记录。当前版本来自 Agent 实际回报。</p></div></div></section></div></template>
<style scoped>.engine-manager{width:min(900px,94vw)}.engine-history{display:grid;gap:10px}.engine-history article{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:14px;border:1px solid var(--border);border-radius:10px}.engine-history small{display:block;color:var(--muted);margin-top:6px}.engine-history p{font-size:12px;overflow-wrap:anywhere}.engine-manager .fields>div{min-width:0}.engine-manager .row-actions{align-self:end;flex-wrap:wrap}.engine-manager .form-note{line-height:1.8}@media(max-width:540px){.engine-history article{flex-direction:column}.engine-manager .row-actions button{flex:1}}</style>
